const upsertSwarmTicket = `-- name: UpsertSwarmTicket :exec

INSERT INTO swarm_tickets (id, identifier, title, description, status, priority, assignee, labels, parent_id, project_id, url, created_at, updated_at, synced_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
ON CONFLICT(id) DO UPDATE SET
    title = excluded.title,
    description = excluded.description,
    status = excluded.status,
    priority = excluded.priority,
    assignee = excluded.assignee,
    labels = excluded.labels,
    parent_id = excluded.parent_id,
    project_id = excluded.project_id,
    url = excluded.url,
    updated_at = excluded.updated_at,
    synced_at = datetime('now')
`

type UpsertSwarmTicketParams struct {
	ID          string
	Identifier  string
	Title       string
	Description sql.NullString
	Status      string
	Priority    sql.NullInt64
	Assignee    sql.NullString
	Labels      sql.NullString
	ParentID    sql.NullString
	ProjectID   sql.NullString
	Url         string
	CreatedAt   string
	UpdatedAt   string
}

// swarm_tickets
func (q *Queries) UpsertSwarmTicket(ctx context.Context, arg UpsertSwarmTicketParams) error {
	_, err := q.db.ExecContext(ctx, upsertSwarmTicket,
		arg.ID,
		arg.Identifier,
		arg.Title,
		arg.Description,
		arg.Status,
		arg.Priority,
		arg.Assignee,
		arg.Labels,
		arg.ParentID,
		arg.ProjectID,
		arg.Url,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	return err
}

